/*
PLAN
1) Composition: graded 7x5.5 backdrop plane at z=-1.5; hero line "TIME, MACHINED." centered at y=0.4 with per-word z offsets (0.12/0/-0.12); accent underline rule at y=-0.05; caption kicker at y=1.15; subhead at y=-0.65; radial contact-glow plate low in frame for depth.
2) Light rig (rig-split-contrast): warm key spot #f6f2ec int 55 at (2.9,1.5,0.4), red kicker spot #ff2a38 int 48 at (-2.9,1.5,0.4), white rim directional 1.1 at (0,2.6,-2.6), ambient floor 0.06 — all node-local.
3) Materials: TSL gradient node backdrop (#0b0b10 -> #13131a) with 1.5% mono grain; emissive accent rule (#ff2a38, intensity 1.2); MSDF text via ctx.fontAtlas in paper #e8ecf2 / accent slash in caption.
4) Motion: kinetic-text primitive on load (60ms stagger, 0.35 rise) + GSAP fallback-companion: underline scaleX 0->1 anchored left after last glyph, subhead fade-up, group weighted-settle 1.04->1.0 power4.out 0.9s. Idle: breathing <=2% on hero group.
5) Focal element: the hero headline "TIME, MACHINED." — brightest read (paper glyphs under key + red kicker); everything else graded below it.
*/
import { Group, Mesh, PlaneGeometry, CircleGeometry, SpotLight, DirectionalLight, AmbientLight, Object3D, Color, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, fract, sin, dot, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'kinetic-type-headline';

  const colors = config.intent?.visualSpec?.colors ?? {};
  const C = {
    background: colors.background ?? '#0b0b10',
    surface: colors.surface ?? '#101017',
    ink: colors.ink ?? '#16161d',
    paper: colors.paper ?? '#e8ecf2',
    accent: colors.accent ?? '#ff2a38',
  };
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#13131a' }];

  const disposables = [];
  const timelines = [];
  const primHandles = [];

  // ---------- backdropStage: engineered vertical gradient + 1.5% mono grain ----------
  const bgGeo = new PlaneGeometry(7, 5.5);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const c0 = new Color(stops[0].hex);
    const c1 = new Color(stops[stops.length - 1].hex);
    const t = uv().y;
    const grad = mix(vec3(c0.r, c0.g, c0.b), vec3(c1.r, c1.g, c1.b), smoothstep(0.0, 1.0, t));
    // cheap hash grain, +/-1.5% mono
    const n = fract(sin(dot(uv().mul(917.0), vec3(12.9898, 78.233, 0).xy)).mul(43758.5453));
    const grain = n.sub(0.5).mul(0.03);
    bgMat.colorNode = vec4(grad.add(vec3(grain, grain, grain)), float(1.0));
  }
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -1.5);
  root.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // surface plinth strip low in frame (color.surface, ink shadow read)
  const plinthGeo = new PlaneGeometry(5.2, 0.9);
  const plinthMat = new MeshBasicNodeMaterial();
  {
    const cs = new Color(C.surface);
    const ci = new Color(C.ink);
    const g = mix(vec3(ci.r, ci.g, ci.b), vec3(cs.r, cs.g, cs.b), smoothstep(0.0, 1.0, uv().y));
    plinthMat.colorNode = vec4(g, float(1.0));
  }
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.set(0, -1.9, -1.2);
  root.add(plinth);
  disposables.push(plinthGeo, plinthMat);

  // radial contact glow under hero (depth plane 3)
  const glowGeo = new CircleGeometry(1.9, 48);
  const glowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const ci = new Color(C.ink);
    const d = uv().sub(0.5).length().mul(2.0);
    const a = smoothstep(1.0, 0.0, d).mul(0.5);
    glowMat.colorNode = vec4(vec3(ci.r, ci.g, ci.b), a);
  }
  const contact = new Mesh(glowGeo, glowMat);
  contact.position.set(0, -1.35, -0.9);
  root.add(contact);
  disposables.push(glowGeo, glowMat);

  // ---------- lightRig: rig-split-contrast (node-local) ----------
  const lightRig = new Group();
  const keyTarget = new Object3D(); keyTarget.position.set(0, 0.5, 0); lightRig.add(keyTarget);
  const key = new SpotLight('#f6f2ec', 55, 0, 0.5, 0.4);
  key.position.set(2.9, 1.5, 0.4); key.target = keyTarget; lightRig.add(key);
  const kicker = new SpotLight(C.accent, 48, 0, 0.5, 0.4);
  kicker.position.set(-2.9, 1.5, 0.4); kicker.target = keyTarget; lightRig.add(kicker);
  const rimTarget = new Object3D(); rimTarget.position.set(0, 0.6, 0); lightRig.add(rimTarget);
  const rim = new DirectionalLight('#ffffff', 1.1);
  rim.position.set(0, 2.6, -2.6); rim.target = rimTarget; lightRig.add(rim);
  const ambient = new AmbientLight('#ffffff', 0.06);
  lightRig.add(ambient);
  root.add(lightRig);

  // ---------- text content (bridging idiom, verbatim copy) ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role, fallback) => {
    const it = items.find((i) => i.role === role);
    return it ? it.text : fallback;
  };
  const captionCopy = byRole('caption', 'NOVA ATELIER / CALIBRE PROGRAM');
  const heroCopy = byRole('hero', 'TIME, MACHINED.');
  const subheadCopy = byRole('subhead', 'Every calibre begins as a solid billet.');

  // caption kicker at y=1.15, mono 700 uppercase, wide tracking
  const caption = ctx.fontAtlas.createText(captionCopy.toUpperCase(), {
    fontSize: 18,
    color: C.paper,
    align: 'center',
    letterSpacingPx: 2.2,
  });
  caption.position.set(0, 1.15, 0.05);
  root.add(caption);

  // ---------- heroGroup: per-word MSDF planes with z parallax ----------
  const heroGroup = new Group();
  heroGroup.name = 'heroGroup';
  heroGroup.position.set(0, 0.4, 0);
  const words = heroCopy.split(' ');
  const zOffsets = [0.12, 0.0, -0.12];
  const wordNodes = [];
  {
    // lay words on one centered line; approximate advance via char count * em width
    const em = 0.62;
    const charW = em * 0.56;
    const gap = em * 0.32;
    const widths = words.map((w) => w.length * charW);
    const total = widths.reduce((a, b) => a + b, 0) + gap * (words.length - 1);
    let x = -total / 2;
    words.forEach((w, i) => {
      const node = ctx.fontAtlas.createText(w, {
        fontSize: 124,
        color: C.paper,
        align: 'left',
        letterSpacingPx: -1.2,
      });
      node.position.set(x + widths[i] / 2, 0, zOffsets[i % zOffsets.length]);
      heroGroup.add(node);
      wordNodes.push(node);
      x += widths[i] + gap;
    });
  }
  root.add(heroGroup);

  // ---------- accentRule: emissive underline, scaleX anchored left ----------
  const ruleGeo = new PlaneGeometry(2.6, 0.045);
  ruleGeo.translate(1.3, 0, 0); // left-anchor
  const ruleMat = new MeshBasicNodeMaterial();
  {
    const ca = new Color(C.accent);
    ruleMat.colorNode = vec4(vec3(ca.r, ca.g, ca.b).mul(1.2), float(1.0));
  }
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(-1.3, -0.05, 0.02);
  rule.scale.x = 0.0001;
  root.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // subhead at y=-0.65
  const subhead = ctx.fontAtlas.createText(subheadCopy, {
    fontSize: 40,
    color: C.paper,
    align: 'center',
  });
  subhead.position.set(0, -0.85, 0.05);
  root.add(subhead);

  // ---------- primitives from config (kinetic-text on load) ----------
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives[p.name];
    if (fn) primHandles.push(fn(heroGroup, p.params ?? {}));
  }

  // ---------- entranceMotion: word stagger + weighted settle + rule + subhead ----------
  const setOpacity = (obj, v) => {
    obj.traverse((o) => {
      if (o.material) { o.material.transparent = true; o.material.opacity = v; }
    });
  };
  wordNodes.forEach((n) => { n.position.y += 0.35; setOpacity(n, 0); });
  setOpacity(subhead, 0);
  subhead.position.y -= 0.2;
  setOpacity(caption, 0);

  const tl = gsap.timeline();
  timelines.push(tl);
  tl.to({}, { duration: 0.05 });
  wordNodes.forEach((n, i) => {
    const at = i * 0.06 * (n.children?.length || 1);
    tl.to(n.position, { y: n.position.y - 0.35, duration: 0.7, ease: 'power2.out' }, at);
    const st = { v: 0 };
    tl.to(st, { v: 1, duration: 0.7, ease: 'power2.out', onUpdate: () => setOpacity(n, st.v) }, at);
  });
  const lastLand = (wordNodes.length - 1) * 0.06 + 0.7;
  // weighted settle 1.04 -> 1.0
  tl.set(heroGroup.scale, { x: 1.04, y: 1.04, z: 1.04 }, lastLand);
  tl.to(heroGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, lastLand);
  // rule scaleX 0->1, 120ms after last glyph lands
  tl.to(rule.scale, { x: 1, duration: 0.5, ease: 'power2.out' }, lastLand + 0.12);
  // subhead fade-up
  const ss = { v: 0 };
  tl.to(subhead.position, { y: subhead.position.y + 0.2, duration: 0.5, ease: 'power2.out' }, lastLand + 0.2);
  tl.to(ss, { v: 1, duration: 0.5, ease: 'power2.out', onUpdate: () => setOpacity(subhead, ss.v) }, lastLand + 0.2);
  const cs = { v: 0 };
  tl.to(cs, { v: 1, duration: 0.5, ease: 'power2.out', onUpdate: () => setOpacity(caption, cs.v) }, 0.1);

  // idle breathing <=2% on hero group (single slow transform)
  const idle = gsap.to(heroGroup.scale, {
    x: 1.015, y: 1.015, z: 1.015,
    duration: 3.2, ease: 'sine.inOut', yoyo: true, repeat: -1, delay: lastLand + 1.0,
  });
  timelines.push(idle);

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primHandles.forEach((h) => h?.cleanup?.());
    disposables.forEach((d) => d.dispose?.());
    root.traverse((o) => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) o.material.dispose?.();
    });
  };

  return root;
}

/* @spec-manifest
{"elements":[
{"id":"text.caption.0","where":"caption","how":"MSDF kicker at y=1.15 via byRole"},
{"id":"text.hero.1","where":"heroGroup","how":"per-word MSDF planes with z parallax"},
{"id":"text.subhead.2","where":"subhead","how":"MSDF subhead, fade-up entrance"},
{"id":"color.background","where":"backdropStage","how":"gradient stop 0 on backdrop plane"},
{"id":"color.surface","where":"plinthMat","how":"surface plinth strip gradient"},
{"id":"color.ink","where":"glowMat","how":"ink in plinth and contact glow"},
{"id":"color.paper","where":"heroGroup","how":"paper #e8ecf2 on all text"},
{"id":"color.accent","where":"accentRule","how":"emissive red underline + kicker light"},
{"id":"color.gradient","where":"backdropStage","how":"vertical 2-stop TSL gradient"},
{"id":"effects.spec","where":"entranceMotion","how":"stagger rise, settle, rule, grain"},
{"id":"primitive.kinetic-text","where":"prims loop","how":"ctx.primitives['kinetic-text'](heroGroup, params)"}
]}
*/
